import { View } from 'cerebral'

// Get Vue from global
const Vue = global.Vue
const isVue3 = Vue && Vue.version && Vue.version.startsWith('3')

export default function connect(dependencies, component = {}) {
  // Configure inject for Vue version compatibility
  if (isVue3) {
    if (Array.isArray(component.inject)) {
      if (!component.inject.includes('cerebral_controller')) {
        component.inject = [...component.inject, 'cerebral_controller']
      }
    } else {
      component.inject = component.inject
        ? { ...component.inject, cerebral_controller: { default: null } }
        : { cerebral_controller: { default: null } }
    }
  } else {
    component.inject = component.inject
      ? component.inject.concat(['cerebral_controller'])
      : ['cerebral_controller']
  }

  // Add cerebral update handler
  component.methods = Object.assign(component.methods || {}, {
    _cererebral_onUpdate: function (stateChanges, force) {
      this.view.updateFromState(stateChanges, this.$props, force)
      this.view.render(this.$props, (newProps) => {
        if (isVue3) {
          // In Vue 3, filter out props to avoid mutating read-only props
          const filteredProps = Object.keys(newProps).reduce((props, key) => {
            if (!this.$props || !(key in this.$props)) {
              props[key] = newProps[key]
            }
            return props
          }, {})
          Object.assign(this, filteredProps)
        } else {
          // Vue 2 allows prop mutation in components
          Object.assign(this, newProps)
        }
      })
      this.$forceUpdate()
    },
  })

  // Store existing lifecycle hooks
  const existingBeforeMount = component.beforeMount
  const existingBeforeDestroy = isVue3
    ? component.beforeUnmount
    : component.beforeDestroy
  const existingDestroyed = isVue3 ? component.unmounted : component.destroyed

  // Initialize cerebral on mount
  component.beforeMount = function (...args) {
    existingBeforeMount && existingBeforeMount.call(this, ...args)

    if (!this.cerebral_controller) {
      throw new Error(
        'Cerebral - Can not find controller, did you remember to use the Container component?'
      )
    }

    this.view = new View({
      dependencies,
      mergeProps: null,
      props: this.$props || {},
      controller: this.cerebral_controller,
      displayName: component.name || 'NoName',
      onUpdate: this._cererebral_onUpdate,
    })

    this.view.mount()
    this.view.render(this.$props || {}, (newProps) => {
      if (isVue3) {
        // Filter out props in Vue 3
        const filteredProps = Object.keys(newProps).reduce((props, key) => {
          if (!this.$props || !(key in this.$props)) {
            props[key] = newProps[key]
          }
          return props
        }, {})
        Object.assign(this, filteredProps)
      } else {
        // Vue 2 allows prop mutation
        Object.assign(this, newProps)
      }
    })

    // Setup prop watchers
    if (this.$props) {
      Object.keys(this.$props).forEach((prop) => {
        this.$watch(prop, function (newVal, oldVal) {
          const oldProps = Object.assign({}, this.$props, { [prop]: oldVal })
          const hasUpdate = this.view.onPropsUpdate(oldProps, this.$props)

          if (hasUpdate) {
            this.view.render(this.$props, (newProps) => {
              if (isVue3) {
                // Filter props in Vue 3
                const filteredProps = Object.keys(newProps).reduce(
                  (props, key) => {
                    if (!this.$props || !(key in this.$props)) {
                      props[key] = newProps[key]
                    }
                    return props
                  },
                  {}
                )
                Object.assign(this, filteredProps)
              } else {
                Object.assign(this, newProps)
              }
            })
            this.$forceUpdate()
          }
        })
      })
    }
  }

  // Handle component unmounting based on Vue version
  if (isVue3) {
    component.beforeUnmount = function (...args) {
      existingBeforeDestroy && existingBeforeDestroy.call(this, ...args)
      if (this.view) {
        this.view.unMount()
        this.view = null
      }
    }

    if (existingDestroyed) {
      component.unmounted = function (...args) {
        existingDestroyed.call(this, ...args)
      }
    }
  } else {
    component.beforeDestroy = function (...args) {
      existingBeforeDestroy && existingBeforeDestroy.call(this, ...args)
      if (this.view) {
        this.view.unMount()
        this.view = null
      }
    }

    if (existingDestroyed) {
      component.destroyed = function (...args) {
        existingDestroyed.call(this, ...args)
      }
    }
  }

  // Return appropriate component type for Vue version
  if (isVue3 && Vue.defineComponent) {
    return Vue.defineComponent(component)
  }

  return isVue3 ? component : Vue.extend(component)
}
